// ✅ THE CACHE-ASIDE PATTERN IN C#
public async Task<User> GetUserAsync(int id)
{
    // 1. Check the fast Cache first
    var user = await _cache.GetAsync($"user_{id}");

    if (user == null)
    {
        // 2. Cache miss! Do the slow Database work
        user = await _db.Users.FindAsync(id);

        // 3. Save it in the cache for 10 minutes
        await _cache.SetAsync($"user_{id}", user, TimeSpan.FromMinutes(10));
    }

    return user;
}

