[HttpPost("upload-video")]
public IActionResult Upload()
{
    // We don't process the video here! It takes too long.
    // We just drop a sticky note in the queue.
    _messageQueue.Publish(new VideoEvent { VideoId = 123 });

    return Accepted("Your video is processing!");
}


